<?php require 'config.php'; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $sid=trim($_POST['sid']??''); $name=trim($_POST['name']??''); $email=trim($_POST['email']??''); $dept=trim($_POST['dept']??''); $semester=trim($_POST['semester']??''); $password=$_POST['password']??''; $confirm=$_POST['confirm']??''; if(!$sid||!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$dept||!$semester||strlen($password)<8) $error='Please complete all fields. Password must be at least 8 characters.'; elseif($password!==$confirm) $error='Passwords do not match.'; else { try{$q=$pdo->prepare('INSERT INTO users(student_id,full_name,email,department,semester,password_hash) VALUES(?,?,?,?,?,?)');$q->execute([$sid,$name,$email,$dept,$semester,password_hash($password,PASSWORD_DEFAULT)]);header('Location: login.php?registered=1');exit;}catch(PDOException $e){$error='Student ID or email is already registered.';} } } ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Register | Student Hub</title><style>body{font-family:Arial,sans-serif;background:#f3f6fb;margin:0;color:#17243b}.wrap{max-width:650px;margin:45px auto;background:white;padding:32px;border-radius:16px;box-shadow:0 8px 30px #182c4a18}h1{color:#174c88}label{display:block;margin:14px 0 6px;font-weight:bold}input,select{box-sizing:border-box;width:100%;padding:11px;border:1px solid #c9d3e0;border-radius:7px}button{margin-top:18px;background:#1767b1;color:white;border:0;padding:12px 22px;border-radius:7px;cursor:pointer}.msg{background:#fff3cd;padding:12px;border-radius:7px;margin:12px 0}.nav{margin-bottom:20px}.nav a{margin-right:14px;color:#1767b1}</style></head><body><main class="wrap"><div class="nav"><a href="index.html">Home</a><a href="login.php">Login</a></div><h1>Create Student Account</h1><?php if($error):?><div class="msg"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Student ID</label><input name="sid" required placeholder="24CS001"><label>Full Name</label><input name="name" required><label>Email</label><input type="email" name="email" required><label>Department</label><select name="dept" required><option value="">Select department</option><?php foreach(['CSPIT','DEPSTAR','CMPICA','RPCP','IIIM','PDPIAS','ARIP'] as $d):?><option><?=e($d)?></option><?php endforeach;?></select><label>Semester</label><select name="semester" required><option value="">Select semester</option><?php for($i=1;$i<=8;$i++):?><option>Semester <?=$i?></option><?php endfor;?></select><label>Password (minimum 8 characters)</label><input type="password" name="password" minlength="8" required><label>Confirm Password</label><input type="password" name="confirm" minlength="8" required><button>Create Account</button></form></main></body></html>